create table if not exists public.user_workspace(user_id uuid primary key references auth.users(id) on delete cascade,data jsonb not null default '{"videos":[],"tasks":[],"notes":[]}'::jsonb,updated_at timestamptz not null default now());alter table public.user_workspace enable row level security;drop policy if exists "Read own workspace" on public.user_workspace;drop policy if exists "Insert own workspace" on public.user_workspace;drop policy if exists "Update own workspace" on public.user_workspace;create policy "Read own workspace" on public.user_workspace for select to authenticated using(auth.uid()=user_id);create policy "Insert own workspace" on public.user_workspace for insert to authenticated with check(auth.uid()=user_id);create policy "Update own workspace" on public.user_workspace for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='user_workspace') then alter publication supabase_realtime add table public.user_workspace;end if;end $$;